M("## Anomalies chased to their source\n1. Tree-level m_W, m_Z differ from PDG by 0.16 % and 0.35 %: the electroweak radiative correction Δr, computed below from the on-shell relation. 2. The one-loop λ → 0 scale is extremely sensitive to y_t(M_Z): not a number to quote.")
Cc("import math\nalpha0 = 1/137.035999; GF = S.INPUTS['G_F'][0]; mW = S.pdg_mass('W+')[0]; mZ = S.pdg_mass('Z0')[0]\nA0 = math.pi*alpha0/(math.sqrt(2)*GF); s2 = 1 - mW**2/mZ**2; print('on-shell sin2 = %.5f (MSbar %.5f);  Delta r = %.4f  (literature about 0.036)' % (s2, S.INPUTS['sin2_thetaW_MSbar_MZ'][0], 1 - A0/(mW**2*s2)))\nfrom scipy.integrate import solve_ivp\nM0 = S.pdg_mass('Z0')[0]; k = 1/(16*math.pi**2); g1, g2, g3 = S.gauge_initial(); lam0 = S.higgs_sector()['lam']\ndef cross(yt0):\n    def f(t, y):\n        a1, a2, a3, yy, l = y; gp2 = 3/5*a1**2\n        return [k*41/10*a1**3, -k*19/6*a2**3, -k*7*a3**3, k*yy*(4.5*yy**2 - 8*a3**2 - 9/4*a2**2 - 17/20*a1**2), k*(24*l**2 - 6*yy**4 + 12*l*yy**2 - 3*l*(3*a2**2 + gp2) + 3/8*(2*a2**4 + (a2**2 + gp2)**2))]\n    ev = lambda t, y: y[4]; ev.terminal = True; ev.direction = -1\n    s = solve_ivp(f, (0, math.log(1e19/M0)), [g1, g2, g3, yt0, lam0], events=ev, rtol=1e-9, atol=1e-12)\n    return M0*math.exp(s.t_events[0][0]) if len(s.t_events[0]) else None\nfor yt in (0.92, 0.94, 0.96, 1.00): c = cross(yt); print('y_t(M_Z) = %.2f  lambda crosses zero at %s' % (yt, ('%.2e GeV' % c) if c else 'no scale below 1e19 GeV'))")
